  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/proc/cygdrive/c/Users/arist/Code/keyboard-firmware/node_modules/.pnpm/svelte-check@4.4.8_picomatc_3784ca3b505fb9a59911f1a023db704a/node_modules/svelte-check/node_modules:/proc/cygdrive/c/Users/arist/Code/keyboard-firmware/node_modules/.pnpm/svelte-check@4.4.8_picomatc_3784ca3b505fb9a59911f1a023db704a/node_modules:/proc/cygdrive/c/Users/arist/Code/keyboard-firmware/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
